refused_program.body:
upstream_ref="{upstream_remote}/{upstream_branch}"
base=$(git merge-base HEAD "$upstream_ref")

# Start the merge without committing; conflicts are expected.
git merge --no-commit --no-ff "$upstream_ref" || true

tmpdir=$(mktemp -d)
trap 'rm -rf "$tmpdir"' EXIT

# Resolve each conflicted path by taking upstream's version as the base and
# re-applying only the lines the local side added relative to the merge base.
while IFS= read -r -d '' path; do
  git checkout --theirs -- "$path" 2>/dev/null || git show "$upstream_ref:$path" > "$path"

  git diff --no-color -U0 "$base" HEAD -- "$path" | awk '
    /^@@/ {
      if (want) for (i = 1; i <= n; i++) print plus[i]
      delete plus; n = 0; want = 1; next
    }
    /^---/ || /^\+\+\+/ { next }
    /^-/ { want = 0; next }
    /^\+/ { plus[++n] = substr($0, 2); next }
    END { if (want) for (i = 1; i <= n; i++) print plus[i] }
  ' > "$tmpdir/additions"

  if [ -s "$tmpdir/additions" ]; then
    awk -v addfile="$tmpdir/additions" '
      BEGIN {
        while ((getline a < addfile) > 0) {
          if (a != "") adds[++na] = a
        }
        close(addfile)
      }
      { lines[NR] = $0 }
      END {
        start = 0; end = 0
        for (i = 1; i <= NR; i++) {
          if (lines[i] ~ /^[[:space:]]*packages[[:space:]]*=[[:space:]]*\[[[:space:]]*$/) {
            start = i
          }
          if (start && lines[i] ~ /^[[:space:]]*\][[:space:]]*$/) {
            end = i
            break
          }
        }
        if (start && end) {
          for (i = 1; i < start; i++) print lines[i]
          print lines[start]
          delete inner; ni = 0
          for (i = start + 1; i < end; i++) inner[++ni] = lines[i]
          for (j = 1; j <= na; j++) {
            a = adds[j]
            found = 0
            for (i = 1; i <= ni; i++) if (inner[i] == a) { found = 1; break }
            if (!found) inner[++ni] = a
          }
          for (i = 2; i <= ni; i++) {
            key = inner[i]; j = i - 1
            while (j > 0 && inner[j] > key) { inner[j + 1] = inner[j]; j-- }
            inner[j + 1] = key
          }
          for (i = 1; i <= ni; i++) print inner[i]
          print lines[end]
          for (i = end + 1; i <= NR; i++) print lines[i]
        } else {
          for (i = 1; i <= NR; i++) print lines[i]
          for (j = 1; j <= na; j++) print adds[j]
        }
      }
    ' "$path" > "$tmpdir/resolved"
    mv "$tmpdir/resolved" "$path"
  fi
  git add -- "$path"
done < <(git diff --name-only --diff-filter=U -z)

if git rev-parse --verify --quiet MERGE_HEAD >/dev/null; then
  git commit --no-edit
fi

postconditions.probe:
git rev-parse --verify --quiet HEAD^2 >/dev/null || exit 1
base=$(git merge-base HEAD^1 HEAD^2) || exit 1
while IFS= read -r -d '' path; do
  added=$(git diff --no-color -U0 "$base" HEAD^1 -- "$path" | awk '
    /^@@/ {
      if (want) for (i = 1; i <= n; i++) print plus[i]
      delete plus; n = 0; want = 1; next
    }
    /^---/ || /^\+\+\+/ { next }
    /^-/ { want = 0; next }
    /^\+/ { plus[++n] = substr($0, 2); next }
    END { if (want) for (i = 1; i <= n; i++) print plus[i] }
  ')
  [ -z "$added" ] && continue
  while IFS= read -r line; do
    [ -z "$line" ] && continue
    git show "HEAD:$path" | grep -Fqx -- "$line" || exit 1
  done <<< "$added"
done < <(git diff --name-only -z "$base" HEAD^1)
